import {id as makeId,stamp,tombstone,active} from './storage.js?v=20260923-19';

export const nutrientKeys=['kcal','kj','protein','carbs','sugars','fat','saturatedFat','fibre','sodium','potassium','calcium','iron','magnesium','zinc','vitaminC','vitaminA','folate','cost'];
export const nutrientMeta={kcal:['Calories','kcal'],kj:['Energy','kJ'],protein:['Protein','g'],carbs:['Carbs','g'],sugars:['Sugars','g'],fat:['Fat','g'],saturatedFat:['Saturated fat','g'],fibre:['Fibre','g'],sodium:['Sodium','mg'],potassium:['Potassium','mg'],calcium:['Calcium','mg'],iron:['Iron','mg'],magnesium:['Magnesium','mg'],zinc:['Zinc','mg'],vitaminC:['Vitamin C','mg'],vitaminA:['Vitamin A','µg'],folate:['Folate','µg'],cost:['Cost','']};
export const units=['g','ml','serving','cup','tbsp','tsp','piece','slice'];
export const zero=()=>Object.fromEntries(nutrientKeys.map(key=>[key,key==='cost'?0:null]));
export const known=value=>Number.isFinite(value);
export function totals(entries){const result=zero(),missing={};for(const key of nutrientKeys){const values=entries.map(entry=>entry.nutrition?.[key]),present=values.filter(known);result[key]=present.length?present.reduce((sum,value)=>sum+value,0):(key==='cost'?0:null);missing[key]=values.length-present.length;}result.missing=missing;return result;}
export function scaleNutrition(values,factor){const output=zero();for(const key of nutrientKeys)output[key]=known(values?.[key])?values[key]*factor:null;output.cost=known(values?.cost)?values.cost*factor:0;return output;}
export function ingredientNutrition(ingredient,grams,price){const nutrition={};for(const key of nutrientKeys.filter(key=>key!=='cost'))if(known(ingredient[key]))nutrition[key]=ingredient[key]*grams/100;const source=ingredient.purchaseSource?globalThis.__afterhoursIngredients?.[ingredient.purchaseSource]:null,purchased=source||ingredient,purchaseGrams=grams*(ingredient.purchaseFactor??1),pack=price?.pack||purchased.pack*(purchased.gramsPerUnit||1),packPrice=price?.price??purchased.price;nutrition.cost=pack>0&&known(packPrice)?purchaseGrams/pack*packPrice:0;return nutrition;}
export function makeEntry(record){return stamp({id:record.id||makeId('food'),meal:'snacks',unit:'serving',...record});}
export function mealFromTime(time='12:00'){const hour=Number(time.slice(0,2));return hour<10?'breakfast':hour<15?'lunch':hour<21?'dinner':'snacks';}
export function ensureFoodState(state,recipeNutrition,recipeName){state.customIngredients||={};state.customRecipes||=[];state.hiddenIngredients||=[];state.foodFavorites||=[];state.savedMeals||=[];state.foodCache||=[];state.pantryHave||={};state.diaryNutrients||=['kcal','protein','carbs','fat'];state.foodEntries||=[];if(state.foodSchema!==2){if(!state.foodEntries.length)for(const log of state.foodLogs||[])state.foodEntries.push(makeEntry({id:`legacy-${log.day}`,day:log.day,time:'12:00',meal:'snacks',name:'Logged before the diary',kind:'quick',amount:1,unit:'serving',nutrition:{...zero(),kcal:log.kcal,kj:log.kcal*4.184,protein:log.protein,cost:0}}));for(const log of state.mealLogs||[])if(!(state.foodLogs||[]).some(day=>day.day===log.day)&&!state.foodEntries.some(entry=>entry.id===log.id))state.foodEntries.push(makeEntry({id:log.id,day:log.day,time:log.time||'12:00',meal:mealFromTime(log.time),name:recipeName(log.recipe),kind:'recipe',ref:log.recipe,amount:log.servings,unit:'serving',nutrition:{...zero(),...(log.nutrition||recipeNutrition(log.recipe,log.servings))}}));state.foodSchema=2;}for(const entry of state.foodEntries){entry.meal||=mealFromTime(entry.time);entry.unit||=(entry.kind==='ingredient'?'g':'serving');entry.updatedAt||=new Date().toISOString();entry.nutrition||=zero();for(const key of nutrientKeys)if(!(key in entry.nutrition))entry.nutrition[key]=key==='cost'?0:null;if(!known(entry.nutrition.kj)&&known(entry.nutrition.kcal))entry.nutrition.kj=entry.nutrition.kcal*4.184;}}
export function syncDay(state,day){const nutrition=totals(active(state.foodEntries).filter(entry=>entry.day===day));const old=state.foodLogs.find(log=>log.day===day);state.foodLogs=state.foodLogs.filter(log=>log.day!==day);state.foodLogs.push({day,kcal:nutrition.kcal||0,protein:nutrition.protein||0,complete:old?.complete||false});}
export function deleteEntry(state,entry){const index=state.foodEntries.findIndex(item=>item.id===entry.id);if(index>=0)state.foodEntries[index]=tombstone(state.foodEntries[index]);syncDay(state,entry.day);}
export function frequency(entries){const counts=new Map();for(const entry of active(entries))counts.set(entry.ref||entry.name,(counts.get(entry.ref||entry.name)||0)+1);return counts;}
export function validateFoodExtension(state){if(!state||typeof state!=='object')return;if(state.customIngredients!==undefined){if(!state.customIngredients||typeof state.customIngredients!=='object'||Array.isArray(state.customIngredients))throw Error('Invalid ingredients');for(const item of Object.values(state.customIngredients))for(const key of ['kcal','protein','carbs','fat'])if(key in item&&(!known(item[key])||item[key]<0))throw Error('Invalid ingredient');}if(state.foodEntries!==undefined&&!Array.isArray(state.foodEntries))throw Error('Invalid food entries');const ids=new Set;for(const entry of state.foodEntries||[]){if(typeof entry.id!=='string'||ids.has(entry.id)||!/^[a-zA-Z0-9_-]{1,100}$/.test(entry.id)||!/\d{4}-\d{2}-\d{2}/.test(entry.day)||!['quick','recipe','ingredient','product'].includes(entry.kind)||!known(entry.amount)||entry.amount<=0||!entry.nutrition)throw Error('Invalid food entry');ids.add(entry.id);}if(state.customRecipes!==undefined&&!Array.isArray(state.customRecipes))throw Error('Invalid recipes');}
